/// Regenerate only the fixed-nonce fixture frames. The published values were
/// supplied independently in Plan D / the L6-L7 fixture generator, and are
/// opened by the public consumers.
fn owned_key_vector(name: &str) -> Value {
    use crate::kdf::FileKey;

    let master_bytes = std::array::from_fn(|i| i as u8);
    let child_bytes = std::array::from_fn(|i| 0xa0 + i as u8);
    let master = MasterKey::from_bytes(master_bytes);
    let folder = FileKey::from_bytes(FOLDER_KEY);
    // Task 2275 L12: an L8 owner envelope exists only for a foreign (F) id.
    let file_id = "11111111-1111-8111-8111-111111111111";
    let folder_id = "22222222-2222-4222-8222-222222222222";
    let nonce = std::array::from_fn(|i| i as u8);
    let raw = |blob: beebeeb_types::EncryptedBlob| [blob.nonce, blob.ciphertext].concat();
    let frame = match name {
        "owner_wrapped_file_key" => raw(crate::kdf::purpose_wrap_with_nonce(
            &master,
            crate::kdf::OWNER_FILE_KEY_LABEL,
            file_id.as_bytes(),
            &child_bytes,
            &nonce,
        )
        .expect("seal L8 owner file vector")),
        "owner_wrapped_folder_key" => raw(crate::kdf::purpose_wrap_with_nonce(
            &master,
            crate::kdf::FOLDER_CUSTODY_LABEL,
            folder_id.as_bytes(),
            &FOLDER_KEY,
            &nonce,
        )
        .expect("seal L6 custody vector")),
        "folder_wrapped_file_key" => raw(crate::kdf::wrap_folder_child_with_nonce(
            &folder,
            uuid::Uuid::parse_str(folder_id).unwrap().as_bytes(),
            uuid::Uuid::parse_str(file_id).unwrap().as_bytes(),
            1,
            &FileKey::from_bytes(child_bytes),
            &nonce,
        )
        .expect("seal L7 child vector")),
        _ => unreachable!("owned key vector name"),
    };
    let mut vector = json!({
        "name": name,
        "note": "Independent Plan D AES-GCM/HKDF known answer; fixed nonce for this fixture only. Owner wrapping uses canonical UUID string bytes; the folder key is random, never derived.",
        "master_key_hex": hex(&master_bytes),
        "folder_key_hex": hex(&FOLDER_KEY),
        "child_key_hex": hex(&child_bytes),
        "file_id": file_id,
        "folder_id": folder_id,
        "nonce_hex": hex(&nonce),
        "expected_frame_hex": hex(&frame),
    });
    if name == "owner_wrapped_file_key" {
        vector["note"] = json!(
            "L8 owner file key: HKDF-SHA256(master, domain || canonical item ID string), same context as AAD; independent Python cryptography KAT."
        );
    } else if name == "owner_wrapped_folder_key" {
        vector["note"] = json!(
            "L6 permanent root custody: HKDF-SHA256(master, domain || canonical root ID string), same context as AAD; independent cryptography KAT."
        );
    } else if name == "folder_wrapped_file_key" {
        vector["note"] = json!(
            "L7 child wrap: AAD domain || root UUID bytes || item UUID bytes || kind; independent cryptography KAT."
        );
        vector["shared_folder_id"] = json!(folder_id);
        vector["kind"] = json!(1);
    }
    vector
}

/// Task 2275 L12: the item id classes. Every listed id is fed through the real
/// `new`/`is`/`class` predicates, so the vector pins the accepted text form.
fn item_ids_vector() -> Value {
    use crate::item_id::{is_foreign_item_id, item_class};

    const FOREIGN: [&str; 3] = [
        "11111111-1111-8111-8111-111111111111",
        "aaaaaaaa-bbbb-8ccc-9ddd-eeeeeeeeeeee",
        "00000000-0000-8000-8000-000000000000",
    ];
    const OWNER: [&str; 7] = [
        "11111111-1111-4111-8111-111111111111",
        "22222222-2222-4222-8222-222222222222",
        "ffffffff-ffff-4fff-bfff-ffffffffffff",
        "00000000-0000-0000-0000-000000000000",
        "ffffffff-ffff-ffff-ffff-ffffffffffff",
        // UUID v7 is not a foreign id.
        "0190b0c2-1234-7abc-8def-0123456789ab",
        // Version 8 with the wrong variant is not a foreign id either.
        "11111111-1111-8111-c111-111111111111",
    ];
    let class_of = |id: &str| match item_class(id) {
        Ok(crate::item_id::ItemClass::Foreign) => "foreign",
        Ok(crate::item_id::ItemClass::Owner) => "owner",
        Err(_) => "refused",
    };
    let foreign: Vec<Value> = FOREIGN
        .iter()
        .map(|id| json!({"id": id, "class": class_of(id)}))
        .collect();
    let owner: Vec<Value> = OWNER
        .iter()
        .map(|id| json!({"id": id, "class": class_of(id)}))
        .collect();
    // Text forms that must be refused outright (core returns InvalidInput).
    let refused: Vec<Value> = [
        "AAAAAAAA-BBBB-8CCC-9DDD-EEEEEEEEEEEE",
        "{11111111-1111-8111-8111-111111111111}",
        "11111111111181118111111111111111",
    ]
    .iter()
    .map(|id| {
        json!({
            "id": id,
            "class": class_of(id),
            "is_foreign_error": is_foreign_item_id(id).is_err(),
        })
    })
    .collect();
    json!({
        "name": "item_ids",
        "note": "Task 2275 L12: foreign (F) ids are RFC 9562 UUID version 8 with the RFC 4122 variant in canonical \
            lowercase hyphenated text; every other canonical UUID is an owner (O) id; any other text form is refused \
            with InvalidInput.",
        "foreign": foreign,
        "owner": owner,
        "refused": refused,
    })
}

