/// A name envelope written by `encrypt::encrypt_name_for` under
/// [`GIVEN_FILE_KEY`] (task 1958). A v2 pin records `chunk_format: 2` and is
/// sealed under the name subkey; `Unrecorded` is sealed under the raw key with
/// nothing recorded only while [`crate::encrypt::METADATA_SEAL_WRITE`] is
/// `Legacy` (the read-only phase): at the switch the unpinned vector changes,
/// and the drift guard says so.
fn metadata_name_filekey(name: &str, pin: ExpectedChunkFormat, nonce: [u8; 12]) -> Value {
    let file_key = crate::kdf::FileKey::from_bytes(GIVEN_FILE_KEY);
    let (filename, mime) = ("request-upload.pdf", "application/pdf");
    let name_encrypted =
        encrypt_name_for_with_nonce(&file_key, filename, Some(mime), pin, nonce).expect("seal name under a given key");
    json!({
        "name": name,
        "file_key_hex": hex(&GIVEN_FILE_KEY),
        "name_key_hex": hex(derive_name_key(&file_key).as_bytes()),
        "pin": pin.as_u8(),
        "nonce_hex": hex(&nonce),
        "name_encrypted": name_encrypted,
        "expected_name": filename,
        "expected_mime_type": mime,
        "expected_chunk_format": pin.as_u8(),
        "note": "Fixed nonce for a known-answer test. Written by encrypt_name_for(file_key, name, mime, pin), the \
            name writer for a key that is not derived from the master key (renames, file-request uploads). Read \
            with decrypt_file_metadata_with_key(file_key, name_encrypted): pin 2 opens under the name subkey only; \
            pin 0 opens under the raw file key while METADATA_SEAL_WRITE is Legacy (the read-only phase), and is \
            subkey-sealed after the switch, when this vector is re-published.",
    })
}

/// Deterministic plaintext of `len` bytes.
fn plaintext(len: usize) -> Vec<u8> {
    (0..len).map(|i| (i * 13 + 5) as u8).collect()
}

/// A v2 file written in `chunk_size` frames by the real writer, frame `i` sealed
/// with `nonce(i)`. Frame 0's nonce is the version id every frame binds.
fn chunk_stream_vector(name: &str, plaintext: &[u8], chunk_size: u64, nonce: impl Fn(usize) -> [u8; 12]) -> Value {
    let mk = MasterKey::from_bytes(MASTER_KEY);
    let file_key = derive_file_key(&mk, FILE_ID.as_bytes());
    let chunk_key = derive_chunk_key_v2(&file_key);
    let count = plaintext.len().div_ceil(chunk_size as usize).max(1);
    let nonces: Vec<[u8; 12]> = (0..count).map(&nonce).collect();
    let version_id: [u8; VERSION_ID_LEN] = nonces[0];

    let mut enc = ChunkEncryptor::for_push_with_chunk_size(&mk, FILE_ID, plaintext.len() as u64, chunk_size)
        .and_then(|e| e.with_recorded_pin(ExpectedChunkFormat::V2))
        .and_then(|e| e.with_vector_nonces(nonces.clone()))
        .expect("v2 vector encryptor");
    let mut frames = Vec::new();
    let mut wire = Vec::new();
    for (index, part) in plaintext.chunks(chunk_size as usize).enumerate() {
        let chunk = enc.push_chunk(part).expect("seal v2 frame");
        let is_last = index + 1 == count;
        frames.push(json!({
            "index": index,
            "is_last": is_last,
            "nonce_hex": hex(&nonces[index]),
            "aad_hex": hex(&chunk_aad_v2(FILE_ID.as_bytes(), &version_id, index as u32, is_last)),
            "plaintext_hex": hex(part),
            "frame_hex": hex(&chunk.data),
        }));
        wire.extend_from_slice(&chunk.data);
    }
    let summary = enc.finish().expect("finish v2 vector");
    assert_eq!(summary.chunk_count as usize, count);

    json!({
        "name": name,
        "chunk_format": 2,
        "master_key_hex": hex(&MASTER_KEY),
        "file_id": FILE_ID,
        "file_key_hex": hex(file_key.as_bytes()),
        "chunk_key_hex": hex(chunk_key.as_bytes()),
        "chunk_size": chunk_size,
        "chunk_count": count,
        "version_id_hex": hex(&version_id),
        "frames": frames,
        "wire_hex": hex(&wire),
        "plaintext_hex": hex(plaintext),
        "note": NOTE,
    })
}

/// A v2 file's name metadata: `{"chunk_format":2,"mime_type":..,"name":..}`
/// sealed under the name subkey, exactly the `name_encrypted` a server stores.
fn metadata_v2_name() -> Value {
    let mk = MasterKey::from_bytes(MASTER_KEY);
    let file_key = derive_file_key(&mk, FILE_ID.as_bytes());
    let nonce = [0x5a; 12];
    let (name, mime) = ("vector-v2.pdf", "application/pdf");
    let name_encrypted =
        encrypt_name_with_chunk_format_and_nonce(&mk, FILE_ID, name, Some(mime), ExpectedChunkFormat::V2, nonce)
            .expect("seal v2 name metadata");
    json!({
        "name": "metadata_v2_name",
        "master_key_hex": hex(&MASTER_KEY),
        "file_id": FILE_ID,
        "file_key_hex": hex(file_key.as_bytes()),
        "name_key_hex": hex(derive_name_key(&file_key).as_bytes()),
        "nonce_hex": hex(&nonce),
        "name_encrypted": name_encrypted,
        "expected_name": name,
        "expected_mime_type": mime,
        "expected_chunk_format": 2,
        "note": "Fixed nonce for a known-answer test. Read with decrypt_file_metadata(master_key, file_id, \
            name_encrypted): name subkey first; the pin it returns (V2) is what every content reader of the file \
            must use.",
    })
}

#[cfg(test)]
mod tests {
    #![allow(deprecated)]
    use super::*;

    const VECTORS_PATH: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/../test-vectors/vectors.json");

    fn published() -> Value {
        serde_json::from_str(&std::fs::read_to_string(VECTORS_PATH).expect("read vectors.json")).expect("parse")
    }

    /// The drift guard: every published v2 vector is exactly what core's writer
    /// produces from the fixed inputs today, and the file carries the published version.
    #[test]
    fn published_v2_vectors_match_core() {
        let doc = published();
        assert_eq!(doc["version"].as_u64(), Some(VECTORS_FILE_VERSION));
        let list = doc["vectors"].as_array().expect("vectors array");
        let regenerated = v2_vectors();
        assert_eq!(regenerated.len(), V2_VECTOR_NAMES.len());
        for (want, name) in regenerated.iter().zip(V2_VECTOR_NAMES) {
            let got = list
                .iter()
                .find(|v| v["name"] == name)
                .unwrap_or_else(|| panic!("{name} is missing from vectors.json (run the bless test)"));
            assert_eq!(got, want, "{name} drifted from core's v2 writer");
        }
    }

    /// Every content vector derives the SAME chunk key (one master key, one
    /// file id), so their fixed nonces must never repeat across vectors either
    /// (`with_vector_nonces` only sees one stream). E.g. `0xc0 | i` would reach
    /// the single-frame vector's `0xd0` at i = 16.
    #[test]
    fn fixed_nonces_never_repeat_under_one_key() {
        let mut seen = std::collections::HashSet::new();
        let mut frames = 0;
        for v in v2_vectors().iter().filter(|v| v.get("frames").is_some()) {
            for f in v["frames"].as_array().unwrap() {
                frames += 1;
                let n = f["nonce_hex"].as_str().unwrap().to_string();
                assert!(seen.insert(n.clone()), "nonce {n} repeats under the shared chunk key");
            }
        }
        assert_eq!(frames, 4, "3 stream frames + 1 single frame");
    }

    /// Task 1958: for a key derived from the master key, the per-file-key writer
    /// is byte-for-byte the master-key writer. With the published vector's own
    /// inputs it reproduces the published `metadata_v2_name` exactly.
    #[test]
    fn the_filekey_writer_reproduces_the_published_master_key_name() {
        let doc = published();
        let published = doc["vectors"]
            .as_array()
            .unwrap()
            .iter()
            .find(|v| v["name"] == "metadata_v2_name")
            .expect("metadata_v2_name published")
            .clone();
        let file_key = derive_file_key(&MasterKey::from_bytes(MASTER_KEY), FILE_ID.as_bytes());
        let got = encrypt_name_for_with_nonce(
            &file_key,
            "vector-v2.pdf",
            Some("application/pdf"),
            ExpectedChunkFormat::V2,
            [0x5a; 12],
        )
        .unwrap();
        assert_eq!(got, published["name_encrypted"].as_str().unwrap());
    }

    fn hex_bytes(s: &str) -> [u8; 32] {
        let v: Vec<u8> = (0..s.len() / 2)
            .map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap())
            .collect();
        v.try_into().expect("32 bytes")
    }

    fn published_vector(name: &str) -> Value {
        published()["vectors"]
            .as_array()
            .unwrap()
            .iter()
            .find(|v| v["name"] == name)
            .unwrap_or_else(|| panic!("{name} is missing from vectors.json (run the bless test)"))
            .clone()
    }

    /// SF-0002: the shared readers stay two-convention. A name sealed under the
    /// uppercase id must NOT open through `decrypt_name_metadata`; only the
    /// convention-reporting owner resolver may open it, and it says
    /// `upper_repair` (read-only).
    #[test]
    fn shared_reader_refuses_uppercase_sealed_name() {
        let v = published_vector("upper_repair_v1");
        let master = MasterKey::from_bytes(hex_bytes(v["master_key_hex"].as_str().unwrap()));
        let file_id = v["file_id"].as_str().unwrap();
        let name_encrypted = v["name_encrypted"].as_str().unwrap();
        assert_eq!(v["file_id_upper"].as_str().unwrap(), file_id.to_ascii_uppercase());

        assert!(
            matches!(
                crate::encrypt::decrypt_name_metadata(&master, file_id, name_encrypted),
                Err(crate::CoreError::Decryption)
            ),
            "the shared readers must try only string then binary, never the uppercase repair"
        );

        let (_key, convention) = crate::kdf::owner_file_key_for_name(&master, file_id, name_encrypted)
            .expect("owner resolves the uppercase-sealed file");
        assert_eq!(convention, crate::kdf::OwnerKeyConvention::UpperRepair);
        assert_eq!(convention.as_str(), v["expected_convention"].as_str().unwrap());
    }

    #[test]
    fn owner_file_key_for_name_reports_upper_repair_and_decrypts_the_chunk() {
        let v = published_vector("upper_repair_v1");
        let master = MasterKey::from_bytes(hex_bytes(v["master_key_hex"].as_str().unwrap()));
        let (key, convention) = crate::kdf::owner_file_key_for_name(
            &master,
            v["file_id"].as_str().unwrap(),
            v["name_encrypted"].as_str().unwrap(),
        )
        .expect("owner resolves the uppercase-sealed file");
        assert_eq!(convention, crate::kdf::OwnerKeyConvention::UpperRepair);
        assert_eq!(convention.as_str(), v["expected_convention"].as_str().unwrap());
        assert_eq!(key.as_bytes(), &hex_bytes(v["expected_key_hex"].as_str().unwrap()));

        let frame = hex_vec(v["content_frame_hex"].as_str().unwrap());
        let plaintext =
            crate::encrypt::open_raw_with_aad(&key, &frame, &[]).expect("chunk opens under the resolved key");
        assert_eq!(hex(&plaintext), v["content_plaintext_hex"].as_str().unwrap());
    }

    /// SF-0002 split keys (mobile #246 review): the name and each content
    /// version are resolved independently. The name and version 1 sit under the
    /// uppercase id, version 2 under the lowercase id; using the name's key for
    /// version 2 must fail, and the resolver must never guess.
    #[test]
    fn split_file_resolves_name_and_each_version_independently() {
        let v = published_vector("upper_repair_split_v1");
        let master = MasterKey::from_bytes(hex_bytes(v["master_key_hex"].as_str().unwrap()));
        let file_id = v["file_id"].as_str().unwrap();
        let name_encrypted = v["name_encrypted"].as_str().unwrap();

        let (name_key, name_convention) = crate::kdf::owner_file_key_for_name(&master, file_id, name_encrypted)
            .expect("the split file's name resolves");
        assert_eq!(name_convention, crate::kdf::OwnerKeyConvention::UpperRepair);
        assert_eq!(
            name_convention.as_str(),
            v["expected_name_convention"].as_str().unwrap()
        );
        assert_eq!(
            name_key.as_bytes(),
            &hex_bytes(v["expected_name_key_hex"].as_str().unwrap())
        );

        let v1_frame = hex_vec(v["content_v1_frame_hex"].as_str().unwrap());
        let (v1_key, v1_convention) = crate::kdf::owner_file_key_for_content(&master, file_id, &v1_frame)
            .expect("version 1 resolves under the uppercase key");
        assert_eq!(v1_convention, crate::kdf::OwnerKeyConvention::UpperRepair);
        assert_eq!(
            v1_convention.as_str(),
            v["expected_content_v1_convention"].as_str().unwrap()
        );
        assert_eq!(
            v1_key.as_bytes(),
            &hex_bytes(v["expected_content_v1_key_hex"].as_str().unwrap())
        );
        let v1_plaintext =
            crate::encrypt::open_raw_with_aad(&v1_key, &v1_frame, &[]).expect("version 1 opens under the resolved key");
        assert_eq!(hex(&v1_plaintext), v["content_v1_plaintext_hex"].as_str().unwrap());

        let v2_frame = hex_vec(v["content_v2_frame_hex"].as_str().unwrap());
        let (v2_key, v2_convention) = crate::kdf::owner_file_key_for_content(&master, file_id, &v2_frame)
            .expect("version 2 resolves under the lowercase key");
        assert_eq!(v2_convention, crate::kdf::OwnerKeyConvention::String);
        assert_eq!(
            v2_convention.as_str(),
            v["expected_content_v2_convention"].as_str().unwrap()
        );
        assert_eq!(
            v2_key.as_bytes(),
            &hex_bytes(v["expected_content_v2_key_hex"].as_str().unwrap())
        );
        let v2_plaintext =
            crate::encrypt::open_raw_with_aad(&v2_key, &v2_frame, &[]).expect("version 2 opens under the resolved key");
        assert_eq!(hex(&v2_plaintext), v["content_v2_plaintext_hex"].as_str().unwrap());

        // The shape the fix prevents: the name's uppercase key does not open
        // version 2, so a client cannot re-use it for the edit's content.
        assert!(
            crate::encrypt::open_raw_with_aad(&name_key, &v2_frame, &[]).is_err(),
            "version 2 must not open under the name's uppercase key"
        );

        // Per-version resolution applies the same canonical-id rule as the name.
        let upper_id = v["file_id_upper"].as_str().unwrap();
        assert!(matches!(
            crate::kdf::owner_file_key_for_content(&master, upper_id, &v1_frame),
            Err(crate::CoreError::InvalidInput(_))
        ));
    }

    #[test]
    fn string_convention_row_reports_string() {
        let v = published_vector("upper_repair_v1");
        let master = MasterKey::from_bytes(hex_bytes(v["master_key_hex"].as_str().unwrap()));
        let file_id = v["file_id"].as_str().unwrap();
        let name = crate::encrypt::encrypt_name(&master, file_id, "canonical.txt", None).unwrap();
        let (key, convention) = crate::kdf::owner_file_key_for_name(&master, file_id, &name).unwrap();
        assert_eq!(convention, crate::kdf::OwnerKeyConvention::String);
        assert_eq!(key.as_bytes(), derive_file_key(&master, file_id.as_bytes()).as_bytes());
    }

    #[test]
    fn binary_convention_row_reports_binary() {
        let master = MasterKey::from_bytes(MASTER_KEY);
        let file_id = "7b1e4c2a-9d3f-4a6b-8c5e-1f2a3b4c5d6e";
        let uuid = uuid::Uuid::parse_str(file_id).unwrap();
        let binary_key = derive_file_key(&master, uuid.as_bytes());
        let name = crate::encrypt::encrypt_name_for_with_nonce(
            &binary_key,
            "legacy-binary.bin",
            Some("application/octet-stream"),
            ExpectedChunkFormat::Unrecorded,
            [0x5d; 12],
        )
        .unwrap();
        let (_key, convention) = crate::kdf::owner_file_key_for_name(&master, file_id, &name).unwrap();
        assert_eq!(convention, crate::kdf::OwnerKeyConvention::Binary);
    }

    /// SF-0002 P2-2: only the canonical lowercase hyphenated id is accepted. If
    /// an uppercase id were accepted, the string convention (derived from those
    /// bytes) would match the uppercase-sealed row and report `String`,
    /// defeating the read-only distinction.
    #[test]
    fn uppercase_file_id_is_invalid_input() {
        let v = published_vector("upper_repair_v1");
        let master = MasterKey::from_bytes(hex_bytes(v["master_key_hex"].as_str().unwrap()));
        let upper_id = v["file_id_upper"].as_str().unwrap();
        assert!(matches!(
            crate::kdf::owner_file_key_for_name(&master, upper_id, v["name_encrypted"].as_str().unwrap()),
            Err(crate::CoreError::InvalidInput(_))
        ));
    }

    #[test]
    fn plaintext_and_unopenable_names_are_invalid_input() {
        let master = MasterKey::from_bytes(MASTER_KEY);
        let file_id = "5f0c2a9e-3b1d-4c7e-9a2f-6d8e1b4c7a30";
        assert!(matches!(
            crate::kdf::owner_file_key_for_name(&master, file_id, "plain-name.txt"),
            Err(crate::CoreError::InvalidInput(_))
        ));

        let other = MasterKey::from_bytes([0x77; 32]);
        let foreign = crate::encrypt::encrypt_name(&other, file_id, "foreign.txt", None).unwrap();
        assert!(matches!(
            crate::kdf::owner_file_key_for_name(&master, file_id, &foreign),
            Err(crate::CoreError::InvalidInput(_))
        ));
    }

    fn hex_vec(s: &str) -> Vec<u8> {
        (0..s.len() / 2)
            .map(|i| u8::from_str_radix(&s[i * 2..i * 2 + 2], 16).unwrap())
            .collect()
    }

    /// Writes the v2 vectors (and version 8) into `test-vectors/vectors.json`,
    /// leaving every other vector as it is. Run on purpose only.
    #[test]
    #[ignore]
    fn bless_v2_vectors_into_vectors_json() {
        let mut doc = published();
        let list = doc["vectors"].as_array_mut().expect("vectors array");
        list.retain(|v| !V2_VECTOR_NAMES.iter().any(|n| v["name"] == *n));
        list.extend(v2_vectors());
        doc["version"] = json!(VECTORS_FILE_VERSION);
        std::fs::write(VECTORS_PATH, serde_json::to_string_pretty(&doc).unwrap() + "\n").expect("write");
    }
}
